import { useEffect, useId, useRef, useState, type FormEvent } from "react";
import {
  Button,
  Choice,
  ChoiceGroup,
  Flex,
  Heading,
  Price,
  ProductGallery,
  QuantityInput,
  Text,
} from "@paraxe/react";
import {
  sampleProduct,
  validateProductVariants,
  defaultPurchaseLabels,
  getProductPurchase,
  productPurchaseKey,
  type ProductPage01Props,
} from "../shared/product";
import "../shared/product-page.css";

export function ProductPage01({
  as: Tag = "main",
  product = sampleProduct,
  backHref = "/shop",
  backLabel = "Back to the collection",
  eyebrow = "SAMPLE COLLECTION / DEVELOPMENT PREVIEW",
  priceNote = "/ sample price",
  availabilityHeading = "Sizes & availability",
  outOfStockLabel = "Out of stock",
  inStockLabel = "in stock",
  notice,
  addToCart,
  purchaseLabels,
}: ProductPage01Props) {
  validateProductVariants(product.variants);
  const labels = { ...defaultPurchaseLabels, ...purchaseLabels };
  const key = productPurchaseKey(product);
  const [selection, setSelection] = useState<{
    key: string;
    size: string | null;
    quantity: number;
  }>({ key, size: null, quantity: 1 });
  const [pending, setPending] = useState(false),
    [status, setStatus] = useState<"" | "success" | "error">("");
  const busy = useRef(false),
    currentKey = useRef(key);
  currentKey.current = key;
  const id = useId();
  const size = selection.key === key ? selection.size : null;
  const variant = product.variants.find((item) => item.size === size);
  const quantity = Math.min(
    selection.key === key ? selection.quantity : 1,
    Math.max(1, variant?.stock ?? 1),
  );
  const purchase = getProductPurchase(product, size, quantity);
  useEffect(() => {
    setSelection({ key, size: null, quantity: 1 });
    setStatus("");
  }, [key]);
  useEffect(() => {
    setSelection((current) =>
      current.key === key && current.quantity !== quantity
        ? { ...current, quantity }
        : current,
    );
  }, [key, quantity]);
  function chooseSize(value: string | number | Array<string | number> | null) {
    if (busy.current) return;
    setSelection({
      key,
      size: typeof value === "string" ? value : null,
      quantity: 1,
    });
    setStatus("");
  }
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (busy.current || !addToCart || !purchase) return;
    const submittedKey = key;
    busy.current = true;
    setPending(true);
    setStatus("");
    try {
      await addToCart(purchase);
      if (currentKey.current === submittedKey) setStatus("success");
    } catch {
      if (currentKey.current === submittedKey) setStatus("error");
    } finally {
      busy.current = false;
      setPending(false);
    }
  }
  const effectiveNotice =
    notice ??
    (!addToCart
      ? "This is a sample product. Ordering is unavailable in this preview."
      : "");
  return (
    <Tag className="product-page01">
      <a className="product-page01-back" href={backHref}>
        <Text as="span">{backLabel}</Text>
      </a>
      <Flex className="product-page01-layout" align="start" size="large">
        <div className="product-page01-gallery">
          <ProductGallery
            key={productPurchaseKey(product)}
            images={
              product.images ?? [
                { id: "primary", src: product.imageSrc, alt: product.imageAlt },
              ]
            }
            label={`${product.name}: product images`}
          />
        </div>
        <Flex className="product-page01-info" direction="column" size="large">
          <Text as="span" className="product-page01-eyebrow">
            {eyebrow}
          </Text>
          <Heading level="h1">{product.name}</Heading>
          <Flex className="product-page01-price" align="baseline" size="small">
            <Price
              size="detail"
              amount={product.amount}
              currency={product.currency}
              locale={product.locale}
            />
            {priceNote && (
              <Text as="span" tone="muted">
                {priceNote}
              </Text>
            )}
          </Flex>
          <Text className="product-page01-description" tone="muted">
            {product.description}
          </Text>
          <section
            className="product-page01-availability"
            aria-label={availabilityHeading}
          >
            <Heading level="h2">{availabilityHeading}</Heading>
            {addToCart ? (
              <form
                className="product-page01-purchase"
                aria-label={labels.add}
                aria-busy={pending || undefined}
                onSubmit={submit}
              >
                <ChoiceGroup
                  label={availabilityHeading}
                  modelValue={size}
                  onModelValueChange={chooseSize}
                  disabled={pending}
                >
                  <Flex wrap size="small">
                    {product.variants.map((item) => (
                      <Choice
                        key={item.size}
                        value={item.size}
                        width="auto"
                        disabled={item.stock === 0}
                      >
                        {item.size}
                        {item.stock === 0 && (
                          <span className="commerce-sr-only">
                            {" "}
                            - {outOfStockLabel}
                          </span>
                        )}
                      </Choice>
                    ))}
                  </Flex>
                </ChoiceGroup>
                <p className="product-page01-selection-note">
                  {variant
                    ? variant.stock
                      ? `${variant.stock} ${inStockLabel}`
                      : outOfStockLabel
                    : product.variants.some((item) => item.stock > 0)
                      ? labels.chooseSize
                      : outOfStockLabel}
                </p>
                <Flex
                  className="product-page01-purchase-actions"
                  align="end"
                  wrap
                >
                  <QuantityInput
                    id={`${id}-quantity`}
                    label={labels.quantity}
                    modelValue={quantity}
                    max={Math.max(1, variant?.stock ?? 1)}
                    disabled={pending || !variant?.stock}
                    onModelValueChange={(value) => {
                      if (!busy.current) {
                        setSelection({ key, size, quantity: value });
                        setStatus("");
                      }
                    }}
                  />
                  <Button
                    type="submit"
                    className="product-page01-add"
                    disabled={!purchase}
                    loading={pending}
                  >
                    {pending ? labels.pending : labels.add}
                  </Button>
                </Flex>
                {status && (
                  <p
                    className="product-page01-purchase-status"
                    role={status === "error" ? "alert" : "status"}
                  >
                    {status === "error" ? labels.failure : labels.added}
                  </p>
                )}
              </form>
            ) : product.variants.length ? (
              <dl>
                {product.variants.map((variant) => (
                  <Flex
                    key={variant.size}
                    className="product-page01-stock-row"
                    justify="between"
                    align="baseline"
                    wrap
                  >
                    <dt>{variant.size}</dt>
                    <dd>
                      {variant.stock === 0
                        ? outOfStockLabel
                        : `${variant.stock} ${inStockLabel}`}
                    </dd>
                  </Flex>
                ))}
              </dl>
            ) : (
              <Text tone="muted">{outOfStockLabel}</Text>
            )}
            {effectiveNotice && (
              <Text className="product-page01-notice" tone="muted">
                {effectiveNotice}
              </Text>
            )}
          </section>
        </Flex>
      </Flex>
    </Tag>
  );
}

.product-page01 {
  --product-page01-max-width: var(--container-max-width);
  --product-page01-gutter: var(--container-padding);
  --product-page01-gap: var(--section-content-gap);
  box-sizing: border-box;
  max-width: calc(var(--product-page01-max-width) + var(--product-page01-gutter) * 2);
  width: 100%;
  margin-inline: auto;
  padding: var(--card-padding) var(--product-page01-gutter) var(--space-10);
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.product-page01 *, .product-page01 *::before, .product-page01 *::after { box-sizing: border-box; }
.product-page01 p, .product-page01 h1, .product-page01 h2, .product-page01 dl, .product-page01 dd { margin: 0; }
.product-page01-back { display: inline-flex; align-items: center; min-height: calc(var(--space-4) * 2.75); margin-block-end: var(--space-6); color: inherit; font-size: var(--typography-caption-size); font-weight: var(--font-weight-semibold); text-underline-offset: var(--space-1); }
.product-page01-back:focus-visible { outline: var(--focus-ring-width) solid var(--focus-ring-color); outline-offset: var(--focus-ring-offset); }
.product-page01 .product-page01-layout { gap: var(--product-page01-gap); }
.product-page01-gallery { flex: 1.15 1 0; min-width: 0; }
.product-page01 .product-page01-info { flex: 1 1 0; min-width: 0; padding-block-start: var(--space-4); gap: 0; }
.product-page01-eyebrow { font-size: var(--typography-micro-size); font-weight: var(--font-weight-semibold); letter-spacing: var(--letter-spacing-widest); line-height: var(--line-height-normal); overflow-wrap: anywhere; }
.product-page01 h1 { margin-block: var(--space-6); font-size: var(--typography-product-title-size); line-height: var(--line-height-tight); letter-spacing: var(--letter-spacing-tighter); font-weight: var(--font-weight-bold); overflow-wrap: anywhere; }
.product-page01 .product-page01-price { margin-block-start: var(--space-1); gap: var(--inline-gap-sm); flex-wrap: wrap; }
.product-page01-price > .text-muted { font-size: var(--typography-caption-size); }
.product-page01-description { margin-block: var(--space-8); font-size: var(--font-size-base); line-height: var(--line-height-relaxed); }
.product-page01 .product-page01-description { margin-block: var(--space-8); }
.product-page01-availability { width: 100%; }
.product-page01-availability h2 { font-size: var(--font-size-base); line-height: var(--line-height-normal); font-weight: var(--font-weight-semibold); margin-block-end: var(--space-3); }
.product-page01 .product-page01-stock-row { min-height: calc(var(--space-4) * 3); gap: var(--inline-gap); padding-block: var(--space-3); border-block-end: var(--border-width-thin) solid var(--border-default); }
.product-page01-stock-row dt { font-size: var(--typography-caption-size); font-weight: var(--font-weight-semibold); }
.product-page01-stock-row dd { font-size: var(--typography-caption-size); color: var(--text-muted); text-align: end; }
.product-page01 .product-page01-notice { margin-block-start: var(--space-4); font-size: var(--typography-caption-size); line-height: var(--line-height-relaxed); }
@media (max-width: 64rem) { .product-page01 { --product-page01-gap: calc(var(--space-4) * 2.5); } }
@media (max-width: 48rem) {
  .product-page01 { --product-page01-gutter: var(--space-4); }
  .product-page01 .product-page01-layout { flex-direction: column; gap: var(--inline-gap-lg); }
  .product-page01-gallery, .product-page01 .product-page01-info { width: 100%; flex-basis: auto; }
  .product-page01 .product-page01-info { padding-block-start: 0; }
  .product-page01 h1 { font-size: var(--typography-product-title-size); }
}

.product-page01-purchase { width: 100%; padding-block-start: var(--space-3); }
.product-page01 .product-page01-selection-note { margin-block: var(--space-4); color: var(--text-muted); font-size: var(--typography-caption-size); }
.product-page01 .product-page01-purchase-actions { gap: var(--space-4); padding-block-start: var(--space-2); }
.product-page01 .product-page01-add { flex: 1 1 50%; }
.product-page01 .product-page01-purchase-status { margin-block-start: var(--space-4); font-size: var(--typography-caption-size); line-height: var(--line-height-relaxed); }
.product-page01 .product-page01-purchase-status[role="alert"] { color: var(--color-danger); }

import type { ProductGalleryImage } from "@paraxe/core";
export interface ProductPage01Variant {
  id?: string;
  size: string;
  stock: number;
}
export interface ProductPage01Product {
  id?: string;
  name: string;
  amount: number;
  currency: string;
  locale: string;
  description: string;
  images?: readonly ProductGalleryImage[];
  imageSrc?: string;
  imageAlt: string;
  variants: readonly ProductPage01Variant[];
}
export interface ProductPage01Props {
  as?: "main" | "section";
  product?: ProductPage01Product;
  backHref?: string;
  backLabel?: string;
  eyebrow?: string;
  priceNote?: string;
  availabilityHeading?: string;
  outOfStockLabel?: string;
  inStockLabel?: string;
  notice?: string;
  addToCart?: (selection: ProductPage01Purchase) => void | Promise<void>;
  purchaseLabels?: Partial<ProductPage01PurchaseLabels>;
}
export const sampleProduct: ProductPage01Product = {
  id: "academy-training-jersey",
  name: "Academy training jersey",
  amount: 28,
  currency: "GBP",
  locale: "en-GB",
  description:
    "Training wear. A concept for the academy collection, designed around life on and off the pitch. This is a fictional visual sample; designs, prices and availability are illustrative.",
  imageSrc: "/paraxe/product-page-01/jersey.svg",
  imageAlt:
    "Black academy training jersey with yellow collar and chest mark, front view",
  variants: [
    { size: "XS", stock: 0 },
    { size: "S", stock: 8 },
    { size: "M", stock: 8 },
    { size: "L", stock: 8 },
    { size: "XL", stock: 8 },
  ],
};
export function validateProductVariants(
  variants: readonly ProductPage01Variant[],
): void {
  const sizes = new Set<string>();
  for (const variant of variants) {
    const size = variant.size.trim();
    if (
      !size ||
      sizes.has(size) ||
      !Number.isSafeInteger(variant.stock) ||
      variant.stock < 0
    )
      throw new RangeError(
        "Availability rows require unique size labels and non-negative integer stock.",
      );
    sizes.add(size);
  }
}

export interface ProductPage01Purchase {
  product: ProductPage01Product;
  variant: ProductPage01Variant;
  quantity: number;
}
export interface ProductPage01PurchaseLabels {
  chooseSize: string;
  quantity: string;
  add: string;
  pending: string;
  added: string;
  failure: string;
}
export const defaultPurchaseLabels: ProductPage01PurchaseLabels = {
  chooseSize: "Choose a size to continue.",
  quantity: "Quantity",
  add: "Add to cart",
  pending: "Adding to cart...",
  added: "Added to cart.",
  failure: "Could not add this item. Please try again.",
};
/** Snapshot the submitted selection; later prop/inventory changes cannot mutate it. */
export function getProductPurchase(
  product: ProductPage01Product,
  size: string | null,
  quantity: number,
): ProductPage01Purchase | null {
  validateProductVariants(product.variants);
  const variant = product.variants.find((item) => item.size === size);
  if (
    !variant ||
    variant.stock < 1 ||
    !Number.isSafeInteger(quantity) ||
    quantity < 1 ||
    quantity > variant.stock
  )
    return null;
  return {
    product: {
      ...product,
      images: product.images?.map(image => ({ ...image })),
      variants: product.variants.map((item) => ({ ...item })),
    },
    variant: { ...variant },
    quantity,
  };
}
export function productPurchaseKey(product: ProductPage01Product): string {
  return product.id ?? product.name;
}

/** Replaceable local artwork demonstrating a full view and a detail crop. */
export const sampleProductImages: readonly ProductGalleryImage[] = [
 {id:"front",src:"/paraxe/product-page-01/jersey.svg",alt:sampleProduct.imageAlt},
 {id:"collar",src:"/paraxe/product-page-01/jersey-detail.svg",alt:"Training jersey collar and chest detail"},
];
